from pathlib import Path
import sys

p = Path(sys.argv[1]) if len(sys.argv) > 1 else Path('psico-engine.js')
s = p.read_text(encoding='utf-8')
marker = "\n/* PLACURSO_PHASE3A_GAMES */\n"
if marker in s:
    raise SystemExit('Fase 3A já aplicada.')

script = r'''\n/* PLACURSO_PHASE3A_GAMES */\n(function(){\n  function boot(){\n    var hub=document.querySelector('.pch-games-hub');\n    if(!hub || hub.dataset.phase3a==='1') return;\n    hub.dataset.phase3a='1';\n    var KEY='placurso_phase3a_games_v1';\n    var state={plays:0,xp:0,best:0,by:{memoria:{plays:0,correct:0},reflexo:{plays:0,correct:0},dinheiro:{plays:0,correct:0},negocio:{plays:0,correct:0}}};\n    try{state=Object.assign(state,JSON.parse(localStorage.getItem(KEY)||'{}'));}catch(e){}\n    state.by=Object.assign({memoria:{plays:0,correct:0},reflexo:{plays:0,correct:0},dinheiro:{plays:0,correct:0},negocio:{plays:0,correct:0}},state.by||{});\n    function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){}}\n    var css=document.createElement('style');\n    css.textContent='.pch-phase3a{margin:18px 0;padding:16px;border:1px solid #D9C8A7;border-radius:20px;background:#fffdf8}.pch-phase3a-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:12px}.pch-phase3a-head h3{margin:0;font-size:20px}.pch-phase3a-head p{margin:5px 0 0;color:#756D60;font-size:12px;line-height:1.45}.pch-phase3a-badge{padding:6px 9px;border-radius:999px;background:#202A24;color:#F7EBD1;font-size:9px;font-weight:900;white-space:nowrap}.pch-phase3a-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.pch-phase3a-card{border:1px solid #E0D5C2;border-radius:16px;background:#fff;padding:12px;text-align:left;min-height:158px;cursor:pointer}.pch-phase3a-card:active{transform:scale(.99)}.pch-phase3a-icon{font-size:24px}.pch-phase3a-card strong{display:block;margin-top:7px;font-size:13px}.pch-phase3a-card small{display:block;margin-top:5px;color:#756D60;line-height:1.35;font-size:10px}.pch-phase3a-tags{display:flex;flex-wrap:wrap;gap:4px;margin-top:9px}.pch-phase3a-tag{padding:4px 6px;border-radius:999px;background:#F1ECE3;font-size:8px;font-weight:900;color:#574E42}.pch-phase3a-panel{display:none;margin-top:12px;padding:14px;border:1px solid #D9C8A7;border-radius:16px;background:#F9F5EC}.pch-phase3a-panel.is-open{display:block}.pch-phase3a-top{display:flex;justify-content:space-between;gap:8px}.pch-phase3a-title{font-weight:900}.pch-phase3a-meta{font-size:10px;color:#756D60}.pch-phase3a-question{margin:14px 0 10px;font-size:18px;font-weight:900;line-height:1.3}.pch-phase3a-options{display:grid;grid-template-columns:1fr 1fr;gap:8px}.pch-phase3a-btn{min-height:48px;border:1px solid #D7CDBD;border-radius:12px;background:#fff;font-weight:900}.pch-phase3a-btn.primary{background:#202A24;color:#fff;border-color:#202A24}.pch-phase3a-result{margin-top:10px;padding:11px;border-radius:12px;background:#EEE6D6;font-size:12px;line-height:1.5}.pch-phase3a-progress{height:7px;background:#E7DFD0;border-radius:99px;overflow:hidden;margin:10px 0}.pch-phase3a-progress span{display:block;height:100%;background:#A43D2F;width:0}.pch-phase3a-summary{margin-top:10px;font-size:10px;color:#756D60}.pch-phase3a-close{margin-top:9px;width:100%}@media(max-width:720px){.pch-phase3a-head{flex-direction:column}.pch-phase3a-grid{grid-template-columns:1fr 1fr}.pch-phase3a-card{min-height:145px}.pch-phase3a-options{grid-template-columns:1fr}}';\n    document.head.appendChild(css);\n\n    var section=document.createElement('section');\n    section.className='pch-phase3a';\n    section.innerHTML='<div class="pch-phase3a-head"><div><span class="pch-games-eyebrow">ANNAN · FASE 3A</span><h3>Experiências que evoluem</h3><p>Quatro motores simples para treinar memória, velocidade, dinheiro e decisões de negócio. Cada nível acrescenta tempo, variáveis e experiência.</p></div><span class="pch-phase3a-badge">4 NOVOS JOGOS</span></div><div class="pch-phase3a-grid"><button class="pch-phase3a-card" data-p3a="memoria"><span class="pch-phase3a-icon">🧠</span><strong>Memória em cadeia</strong><small>Observe a sequência e reconstrua-a.</small><div class="pch-phase3a-tags"><span class="pch-phase3a-tag">MEMÓRIA</span><span class="pch-phase3a-tag">MENTE</span></div></button><button class="pch-phase3a-card" data-p3a="reflexo"><span class="pch-phase3a-icon">⚡</span><strong>Reflexo rápido</strong><small>Responda apenas ao sinal certo.</small><div class="pch-phase3a-tags"><span class="pch-phase3a-tag">REFLEXO</span><span class="pch-phase3a-tag">FOCO</span></div></button><button class="pch-phase3a-card" data-p3a="dinheiro"><span class="pch-phase3a-icon">💰</span><strong>Decisão financeira</strong><small>Escolha entre preço, margem e risco.</small><div class="pch-phase3a-tags"><span class="pch-phase3a-tag">DINHEIRO</span><span class="pch-phase3a-tag">DECISÃO</span></div></button><button class="pch-phase3a-card" data-p3a="negocio"><span class="pch-phase3a-icon">♟</span><strong>Mini negócio</strong><small>Administre recursos e escolha a próxima ação.</small><div class="pch-phase3a-tags"><span class="pch-phase3a-tag">NEGÓCIO</span><span class="pch-phase3a-tag">ESTRATÉGIA</span></div></button></div><div class="pch-phase3a-panel" id="annanPhase3aPanel"></div><div class="pch-phase3a-summary">ANNAN acompanha as tentativas nesta experiência e transforma repetição em prática. Não é diagnóstico psicológico.</div>';
    var anchor=hub.querySelector('#annanMicrogamesPhase1');\n    if(anchor && anchor.parentNode) anchor.parentNode.insertBefore(section,anchor.nextSibling); else hub.appendChild(section);\n\n    var panel=section.querySelector('#annanPhase3aPanel'),level=1,round=0,timer=null,startedAt=0,current=null;\n    var games={\n      memoria:{name:'Memória em cadeia',time:[30,45,60],rounds:[['A sequência é: 3 · 8 · 2. Qual vem primeiro na reconstrução?',['3','8']],['A sequência é: 6 · 1 · 9. Qual é o último?',['9','1']],['A sequência é: 4 · 7 · 5. Qual é o elemento do meio?',['7','4']]]},\n      reflexo:{name:'Reflexo rápido',time:[20,30,45],rounds:[['SINAL: responda ao círculo diferente → ● ● ○ ●',['○','●']],['SINAL: responda ao quadrado → ■ ● ● ●',['■','●']],['SINAL: responda ao triângulo → ● ▲ ● ●',['▲','●']]]},\n      dinheiro:{name:'Decisão financeira',time:[40,55,70],rounds:[['Venda por 100 e custo 70. Qual é a margem sobre o preço?',['30%','70%']],['Custo 80 e venda 120. Qual é o lucro por unidade?',['40','200']],['Preço 200, custo 150. Se baixares 10 no preço, o lucro fica:',['40','50']]]},\n      negocio:{name:'Mini negócio',time:[45,60,75],rounds:[['Tens 3 clientes e pouca capacidade. O melhor primeiro passo é:',['Priorizar pedidos','Aceitar tudo']],['Vendas caíram. Antes de baixar o preço, deves:',['Descobrir a causa','Dar desconto']],['Um produto vende muito mas quase não dá lucro. Deves:',['Rever a margem','Produzir mais']]]}\n    };\n    function render(kind){\n      current=kind;var g=games[kind],r=g.rounds[Math.floor(Math.random()*g.rounds.length)];startedAt=Date.now();panel.classList.add('is-open');panel.innerHTML='<div class="pch-phase3a-top"><span class="pch-phase3a-title">'+g.name+'</span><span class="pch-phase3a-meta">Nível '+level+' · '+(level*10)+' XP</span></div><div class="pch-phase3a-progress"><span style="width:'+Math.min(100,level*33)+'%"></span></div><div class="pch-phase3a-question">'+r[0]+'</div><div class="pch-phase3a-options"><button class="pch-phase3a-btn primary" data-p3-answer="0">'+r[1][0]+'</button><button class="pch-phase3a-btn" data-p3-answer="1">'+r[1][1]+'</button></div><div class="pch-phase3a-meta" style="margin-top:9px">Tempo do nível: '+g.time[level-1]+'s · experiência aumenta a cada nível.</div>';\n      clearTimeout(timer);timer=setTimeout(function(){finish(false)},g.time[level-1]*1000);\n      panel.querySelectorAll('[data-p3-answer]').forEach(function(b){b.addEventListener('click',function(){finish(b.dataset.p3Answer==='0');});});\n    }\n    function finish(ok){\n      clearTimeout(timer);var elapsed=Math.max(1,(Date.now()-startedAt)/1000),g=games[current],area=state.by[current];state.plays++;area.plays++;if(ok){state.xp+=level*10;state.best=Math.max(state.best,level);area.correct++;}else state.xp+=2;round++;if(ok && level<3)level++;save();\n      panel.innerHTML='<div class="pch-phase3a-result"><strong>'+(ok?'Acerto. Experiência adquirida.':'Tentativa registada.')+'</strong><br>'+ (ok?'O nível seguinte acrescenta complexidade.':'Revê a regra e tenta novamente; o erro também informa a aprendizagem.')+'<br>ANNAN: nível '+level+' · '+state.xp+' XP · '+Math.round(elapsed)+'s nesta tentativa.</div><button class="pch-phase3a-btn primary pch-phase3a-close" data-p3-replay="1">Continuar</button>';\n      panel.querySelector('[data-p3-replay]').addEventListener('click',function(){render(current);});\n    }\n    section.querySelectorAll('[data-p3a]').forEach(function(card){card.addEventListener('click',function(){level=Math.min(3,Math.max(1,level));render(card.dataset.p3a);});});\n  }\n  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',boot); else boot();\n})();\n'''
s += marker + script
p.write_text(s, encoding='utf-8')
print('OK: Fase 3A adicionada ao motor de jogos.')
